	game.test_mode = true
	root.add_child(game)

func wait_ready() -> int:
	## Waits until the session is PLAYING and the jelly has been grounded and IDLE for SETTLE ticks.
	## Returns the physics frame on whose start it returned (the press tick).
	var streak := 0
	var guard := 0
	while guard < SLOT:
		await physics_frame
		guard += 1
		var r := row_at(now() - 1)
		if not r.is_empty() and r.state == Game.State.PLAYING and r.floor and r.pose == "IDLE":
			streak += 1
		else:
			streak = 0
		if streak >= SETTLE:
			return now()
	return -1

func stationary_hop() -> int:
	var h := await wait_ready()
	key(JUMP_KEY, true)
	await until(h + 2)
	key(JUMP_KEY, false)
	return h

func first_tick_where(from: int, to: int, field: String) -> int:
	for t in range(from, to + 1):
		if row_at(t).get(field, false):
			return t
	return -1

func run() -> void:
	hook = TickHook.new()
	hook.name = "PinTickHook"
	hook.process_physics_priority = 1000
	hook.on_tick = _log_tick
	root.add_child(hook)
