func start_run(name: String) -> void:
	## A fresh game, added at the start of a physics frame that is a multiple of SLOT.
	if is_instance_valid(game):
		run_name = ""
		game.queue_free()
		await process_frame
		await process_frame
	await until((now() / SLOT + 1) * SLOT)
	by_tick.clear()
	reads.clear()
	run_first_logged = false
	run_name = name
	game = Game.new()
	game.test_mode = true
	root.add_child(game)

